#[path="../src/dispatch_window.rs"]mod window;
use window::*;
use serde_json::{Value,json};
fn q()->Value{json!({"id":1,"createdAt":100_000,"activationAt":103_000,"expiresAt":113_000,"retired":false,"action":"sell","side":"NO","executionStyle":"inventoryAON","inventoryExitReason":"maximumAge","filled":0,"quantity":5,"price":"0.055000"})}
#[test]fn fresh_maximum_age_sell_prefetches_before_activation(){let q=q();let s=preflight_stage(&q,true,false,100_000);assert_eq!(s,PreflightStage::MaximumAgeSellPrefetch);assert!(s.may_read_snapshots());assert!(s.may_start_pre_activation_snapshots());assert!(!final_native_window_ready(&q,true,false,100_000));}
#[test]fn six_gets_7500ms_fit_by_prefetch_without_extending_the_quote(){let q=q();let old_start=103_000;let old_finish=old_start+7500;assert_eq!(preflight_stage(&q,true,false,old_start),PreflightStage::Activated);assert!(!final_native_window_ready(&q,true,false,old_finish));let new_start=100_000;assert_eq!(preflight_stage(&q,true,false,new_start),PreflightStage::MaximumAgeSellPrefetch);let new_finish=new_start+7500;assert!(final_native_window_ready(&q,true,false,new_finish));assert_eq!(q["activationAt"],103_000);assert_eq!(q["expiresAt"],113_000);}
#[test]fn completion_before_three_seconds_cannot_dispatch(){let q=q();assert!(preflight_stage(&q,true,false,100_000).may_read_snapshots());assert!(!final_native_window_ready(&q,true,false,102_999));assert!(final_native_window_ready(&q,true,false,103_000));}
#[test]fn ordinary_buy_and_nonmaximum_age_sell_wait_for_native_activation(){for (key,value) in [("action",json!("buy")),("executionStyle",Value::Null),("inventoryExitReason",Value::Null),("inventoryExitReason",json!("profitableAge"))]{let mut q=q();q[key]=value;assert_eq!(preflight_stage(&q,true,false,100_000),PreflightStage::DeferredUntilActivation);assert_eq!(preflight_stage(&q,true,false,103_000),PreflightStage::Activated);}}
#[test]fn attempted_unknown_or_existing_intent_never_starts_prefetch(){let q=q();assert_eq!(preflight_stage(&q,false,false,100_000),PreflightStage::NotNeverAttempted);assert_eq!(preflight_stage(&q,true,true,100_000),PreflightStage::ExistingDurableIntent);assert!(!final_native_window_ready(&q,false,false,104_000));assert!(!final_native_window_ready(&q,true,true,104_000));}
#[test]fn retired_canceled_or_partially_filled_quotes_cannot_prefetch(){for (key,value) in [("retired",json!(true)),("cancelEffectiveAt",json!(104_000)),("cancelEffectiveAt",json!("bad"))]{let mut q=q();q[key]=value;assert_eq!(preflight_stage(&q,true,false,100_000),PreflightStage::RetiredOrCanceled);assert!(!final_native_window_ready(&q,true,false,104_000));}let mut q=q();q["filled"]=json!(1);assert_eq!(preflight_stage(&q,true,false,100_000),PreflightStage::DeferredUntilActivation);}
#[test]fn null_cancel_is_not_a_cancellation(){let mut q=q();q["cancelEffectiveAt"]=Value::Null;assert!(preflight_stage(&q,true,false,100_000).may_start_pre_activation_snapshots());assert!(final_native_window_ready(&q,true,false,104_000));}
#[test]fn lookahead_is_bounded_to_three_seconds(){let mut q=q();q["activationAt"]=json!(104_000);assert_eq!(preflight_stage(&q,true,false,100_000),PreflightStage::DeferredUntilActivation);assert_eq!(preflight_stage(&q,true,false,101_000),PreflightStage::MaximumAgeSellPrefetch);}
#[test]fn short_or_expired_windows_remain_ineligible(){let q=q();assert_eq!(preflight_stage(&q,true,false,108_000),PreflightStage::InsufficientExpiryHeadroom);assert!(!final_native_window_ready(&q,true,false,110_000));assert!(!final_native_window_ready(&q,true,false,113_000));assert!(!final_native_window_ready(&q,true,false,114_000));}
#[test]fn post_snapshot_native_cancellation_or_retirement_blocks_dispatch(){let mut q=q();assert!(preflight_stage(&q,true,false,100_000).may_read_snapshots());q["cancelEffectiveAt"]=json!(109_000);assert!(!final_native_window_ready(&q,true,false,107_500));let mut q=q();q["retired"]=json!(true);assert!(!final_native_window_ready(&q,true,false,107_500));}
#[test]fn malformed_or_future_creation_clocks_do_not_prefetch(){for (key,value) in [("createdAt",json!(100_001)),("activationAt",Value::Null),("activationAt",json!(99_999)),("expiresAt",json!(103_000)),("expiresAt",json!("bad"))]{let mut q=q();q[key]=value;assert_eq!(preflight_stage(&q,true,false,100_000),PreflightStage::InvalidClock);}}
#[test]fn root_must_recheck_native_activation_if_it_changed_during_preflight(){let mut q=q();assert!(preflight_stage(&q,true,false,100_000).may_read_snapshots());q["activationAt"]=json!(108_000);assert!(!final_native_window_ready(&q,true,false,107_500));}
#[test]fn already_expired_before_dispatch_is_not_repaired_by_prefetch(){let q=q();assert_eq!(preflight_stage(&q,true,false,116_000),PreflightStage::InsufficientExpiryHeadroom);assert!(!final_native_window_ready(&q,true,false,116_000));}
